INSERT INTO monster VALUES (563,'Skum','Skum',NULL,'Medium','Aberration','Aquatic','2d8+2 (11 hp)','+1','20 ft. (4 squares), swim 40 ft.','13 (+1 Dex, +2 natural), touch 11, flat-footed 12','+1','+5','Bite +5 melee (2d6+4)','Bite +5 melee (2d6+4) and 2 claws +0 melee (1d4+2)','5 ft.','5 ft.','Rake 1d6+2','Darkvision 60 ft., amphibious','Fort +1, Ref +1, Will +3','Str 19, Dex 13, Con 13, Int 10, Wis 10, Cha 6','Hide +6*, Listen +7*, Move Silently +6, Spot +7*, Swim +12',NULL,'Alertness',NULL,'Underground','Brood (2-5) or pack (6-15)','2','None','Usually lawful evil','3-4 HD (Medium); 5-6 HD (Large)','+3','Rake (Ex)','Skum; CR 2; Medium aberration (aquatic); HD 2d8+2; hp 11; Init +1; Spd 20 ft. (4 squares), swim 40 ft.; AC 13 (+1 dex, +2 natural), touch 11, flat-footed 12; Base Atk +1; Grp +5; Atk +5 melee (2d6+4, bite); Full Atk +5 melee (2d6+4, bite) and +0 melee (1d4+2, 2 claws); Space/Reach 5 ft./5 ft.; SA Rake 1d6+2; SQ Darkvision 60 ft., amphibious; AL LE; SV Fort +1, Ref +1, Will +3; Str 19, Dex 13, Con 13, Int 10, Wis 10, Cha 6\n\nSkills and Feats: Hide +6*, Listen +7*, Move Silently +6, Spot +7*, Swim +12; Alertness','\n      <div topic=\"Skum\" level=\"2\"><p><h2>Skum</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Skum</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Aberration (Aquatic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8+2 (11 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), swim 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>13 (+1 Dex, +2 natural), touch 11, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +5 melee (2d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +5 melee (2d6+4) and 2 claws +0 melee (1d4+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Rake 1d6+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., amphibious<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +1, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 19, Dex 13, Con 13, Int 10, Wis 10, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +6*, Listen +7*, Move Silently +6, Spot +7*, Swim +12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Brood (2-5) or pack (6-15)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>3-4 HD (Medium); 5-6 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n</table><p>A skum is about the same height and weight as a human. Skum speak Aquan.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +0 melee, damage 1d6+2. A skum also gains two rake attacks when it attacks while swimming.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> *Skum have a +4 racial bonus on Hide, Listen, and Spot checks underwater.</p><p>A skum has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (564,'Spectre','Spectre',NULL,'Medium','Undead','Incorporeal','7d12 (45 hp)','+7','40 ft. (8 squares), fly 80 ft. (perfect)','15 (+3 Dex, +2 deflection), touch 15, flat-footed 13','+3','-','Incorporeal touch +6 melee (1d8 plus energy drain)','Incorporeal touch +6 melee (1d8 plus energy drain)','5 ft.','5 ft.','Energy drain, create spawn','Darkvision 60 ft., incorporeal traits, +2 turn resistance, sunlight powerlessness, undead traits, unnatural aura','Fort +2, Ref +5, Will +7','Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15','Hide +13, Intimidate +12, Knowledge (religion) +12, Listen +14, Search +12, Spot +14, Survival +2 (+4 following tracks)',NULL,'Alertness, Blind-Fight, Improved Initiative',NULL,'Any land and underground','Solitary, gang (2-4), or swarm (6-11)','7','None','Always lawful evil','8-14 HD (Medium)','-','Create Spawn (Su), Energy Drain (Su), Sunlight Powerlessness (Ex), Unnatural Aura (Su)','Spectre; CR 7; Medium undead (incorporeal); HD 7d12; hp 45; Init +7; Spd 40 ft. (8 squares), fly 80 ft. (perfect); AC 15 (+3 dex, +2 deflection), touch 15, flat-footed 13; Base Atk +3; Grp -; Atk +6 melee (1d8 plus energy drain, incorporeal touch); Full Atk +6 melee (1d8 plus energy drain, incorporeal touch); Space/Reach 5 ft./5 ft.; SA Energy drain, create spawn; SQ Darkvision 60 ft., incorporeal traits, +2 turn resistance, sunlight powerlessness, undead traits, unnatural aura; AL LE; SV Fort +2, Ref +5, Will +7; Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15\n\nSkills and Feats: Hide +13, Intimidate +12, Knowledge (religion) +12, Listen +14, Search +12, Spot +14, Survival +2 (+4 following tracks); Alertness, Blind-Fight, Improved Initiative','\n      <div topic=\"Spectre\" level=\"2\"><p><h2>Spectre</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Spectre</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Undead (Incorporeal)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>7d12 (45 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares), fly 80 ft. (perfect)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+3 Dex, +2 deflection), touch 15, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Incorporeal touch +6 melee (1d8 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Incorporeal touch +6 melee (1d8 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Energy drain, create spawn<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., incorporeal traits, +2 turn resistance, sunlight powerlessness, undead traits, unnatural aura<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +5, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +13, Intimidate +12, Knowledge (religion) +12, Listen +14, Search +12, Spot +14, Survival +2 (+4 following tracks)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Blind-Fight, Improved Initiative<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any land and underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-4), or swarm (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>8-14 HD (Medium)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A spectre looks much as it did in life and can be easily recognized by those who knew the individual or have seen the individual\'s face in a painting or a drawing. In many cases, the evidence of a violent death is visible on its body. A spectre is roughly human-sized and is weightless.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>In close combat a spectre attacks with its numbing, life-draining touch. It makes full use of its incorporeal nature, moving through walls, ceilings, and floors as it attacks.</p><div topic=\"Energy Drain\" level=\"8\"><p><b>Energy Drain (Su):</b> Living creatures hit by a spectre\'s incorporeal touch attack gain two negative levels. The DC is 15 for the Fortitude save to remove a negative level. The save DC is Charisma-based. For each such negative level bestowed, the spectre gains 5 temporary hit points.</p>\n</div><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a spectre becomes a spectre in 1d4 rounds. Spawn are under the command of the spectre that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p>\n</div><div topic=\"Unnatural Aura\" level=\"8\"><p><b>Unnatural Aura (Su):</b> Animals, whether wild or domesticated, can sense the unnatural presence of a spectre at a distance of 30 feet. They do not willingly approach nearer than that and panic if forced to do so; they remain panicked as long as they are within that range.</p>\n</div><div topic=\"Sunlight Powerlessness\" level=\"8\"><p><b>Sunlight Powerlessness (Ex):</b> Spectres are powerless in natural sunlight (not merely a <i>daylight</i> spell) and flee from it. A spectre caught in sunlight cannot attack and can take only a single move or attack action in a round.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (565,'Sphinx','Androsphinx',NULL,'Large','Magical Beast',NULL,'12d10+48 (114 hp)','+0','50 ft. (10 squares), fly 80 ft. (poor)','22 (-1 size, +13 natural), touch 9, flat-footed 22','+12','+23','Claw +18 melee (2d4+7)','2 claws +18 melee (2d4+7)','10 ft.','5 ft.','Pounce, rake 2d4+3, roar, spells','Darkvision 60 ft., low-light vision','Fort +12, Ref +8, Will +7','Str 25, Dex 10, Con 19, Int 16, Wis 17, Cha 17','Intimidate +17, Knowledge (any one) +18, Listen +18, Spot +18, Survival +18',NULL,'Alertness, Cleave, Great Cleave, Flyby Attack, Power Attack, Track',NULL,'Warm deserts','Solitary','9','Standard','Always chaotic good','13-18 HD (Large); 19-36 HD (Huge)','+5 (cohort)','Pounce (Ex), Rake (Ex), Roar (Su)','Androsphinx; CR 9; Large magical beast; HD 12d10+48; hp 114; Init +0; Spd 50 ft. (10 squares), fly 80 ft. (poor); AC 22 (-1 size, +13 natural), touch 9, flat-footed 22; Base Atk +12; Grp +23; Atk +18 melee (2d4+7, claw); Full Atk +18 melee (2d4+7, 2 claws); Space/Reach 10 ft./5 ft.; SA Pounce, rake 2d4+3, roar, spells; SQ Darkvision 60 ft., low-light vision; AL CG; SV Fort +12, Ref +8, Will +7; Str 25, Dex 10, Con 19, Int 16, Wis 17, Cha 17\n\nSkills and Feats: Intimidate +17, Knowledge (any one) +18, Listen +18, Spot +18, Survival +18; Alertness, Cleave, Flyby Attack, Great Cleave, Power Attack, Track','\n      <div topic=\"Androsphinx\" level=\"3\"><p><h3>Androsphinx</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Androsphinx</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d10+48 (114 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares), fly 80 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>22 (-1 size, +13 natural), touch 9, flat-footed 22<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+12/+23<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +18 melee (2d4+7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +18 melee (2d4+7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Pounce, rake 2d4+3, roar, spells<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +12, Ref +8, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 25, Dex 10, Con 19, Int 16, Wis 17, Cha 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Intimidate +17, Knowledge (any one) +18, Listen +18, Spot +18, Survival +18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Cleave, Great Cleave, Flyby Attack, Power Attack, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-18 HD (Large); 19-36 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+5 (cohort)<br/></td>\n\n</tr>\n</table><p>These sphinxes are always male. Androsphinxes are clever and generally good-natured, but they can be savage opponents.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>In battle, an androsphinx rips apart enemies with its razor-sharp claws. It relies on its natural weapons in a fight, employing its spells for defense or healing.</p><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +18 melee, damage 2d4+3.</p>\n</div><div topic=\"Roar\" level=\"8\"><p><b>Roar (Su):</b> Three times per day an androsphinx can loose a mighty roar. The first time it does this, all creatures within 500 feet must succeed on a DC 19 Will save or be affected as though by a <i>fear</i> spell for 2d6 rounds.</p><p>If the sphinx roars a second time during the same encounter, all creatures within 250 feet must succeed on a DC 19 Fortitude save or be paralyzed for 1d4 rounds, and all those within 90 feet are deafened for 2d6 rounds (no save). If it roars a third time during the same encounter, all those within 250 feet must succeed on a DC 19 Fortitude save or take 2d4 points of Strength damage for 2d4 rounds. In addition, any Medium or smaller creature within 90 feet must succeed on a DC 19 Fortitude save or be thrown to the ground and take 2d8 points of damage. The force of this roar is so great that it deals 50 points of damage to any stone or crystalline object within 90 feet. Magic items and held or carried items can avoid damage with a DC 19 Reflex save. Other androsphinxes are immune to these effects. The save DCs are Charisma-based.</p>\n</div><div topic=\"Spells\" level=\"8\"><p><b>Spells:</b> An androsphinx casts divine spells as a 6th-level cleric from the cleric spell list and from the Good, Healing, and Protection domains.</p><p><i>Typical Cleric Spells Prepared</i> (5/5/5/4; save DC 13 + spell level): 0-<i>cure minor wounds</i>,  <i>detect magic</i>,  <i>guidance</i>,  <i>light</i>,  <i>resistance</i>; 1st-<i>divine favor</i>,  <i>protection from evil*</i>,  <i>shield of faith</i>,  <i>remove fear</i>,  <i>summon monster I</i>; 2nd-<i>bull\'s strength</i>,  <i>remove paralysis</i>,  <i>resist energy</i>,  <i>shield other*</i>,  <i>summon monster II</i>; 3rd-<i>cure serious wounds*</i>,  <i>daylight</i>,  <i>invisibility purge</i>,  <i>searing light</i>.</p><p>*Domain spell. Domains: Good and Healing.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (566,'Sphinx','Criosphinx',NULL,'Large','Magical Beast',NULL,'10d10+30 (85 hp)','+0','30 ft. (6 squares), fly 60 ft. (poor)','20 (-1 size, +11 natural), touch 9, flat-footed 20','+10','+20','Gore +15 melee (2d6+6)','Gore +15 melee (2d6+6) and 2 claws +10 melee (1d6+3)','10 ft.','5 ft.','Pounce, rake 1d6+3','Darkvision 60 ft., low-light vision','Fort +10, Ref +7, Will +3','Str 23, Dex 10, Con 17, Int 10, Wis 11, Cha 11','Intimidate +8, Listen +11, Spot +1',NULL,'Alertness, Cleave, Flyby Attack, Power Attack',NULL,'Warm deserts','Solitary','7','Standard','Always neutral','11-15 HD (Large); 16-30 HD (Huge)','+3 (cohort)','Pounce (Ex), Rake (Ex)','Criosphinx; CR 7; Large magical beast; HD 10d10+30; hp 85; Init +0; Spd 30 ft. (6 squares), fly 60 ft. (poor); AC 20 (-1 size, +11 natural), touch 9, flat-footed 20; Base Atk +10; Grp +20; Atk +15 melee (2d6+6, gore); Full Atk +15 melee (2d6+6, gore) and +10 melee (1d6+3, 2 claws); Space/Reach 10 ft./5 ft.; SA Pounce, rake 1d6+3; SQ Darkvision 60 ft., low-light vision; AL N; SV Fort +10, Ref +7, Will +3; Str 23, Dex 10, Con 17, Int 10, Wis 11, Cha 11\n\nSkills and Feats: Intimidate +8, Listen +11, Spot +1; Alertness, Cleave, Flyby Attack, Power Attack','\n      <div topic=\"Criosphinx\" level=\"3\"><p><h3>Criosphinx</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Criosphinx</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>10d10+30 (85 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), fly 60 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (-1 size, +11 natural), touch 9, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+10/+20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Gore +15 melee (2d6+6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Gore +15 melee (2d6+6) and 2 claws +10 melee (1d6+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Pounce, rake 1d6+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +10, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 23, Dex 10, Con 17, Int 10, Wis 11, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Intimidate +8, Listen +11, Spot +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Cleave, Flyby Attack, Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>11-15 HD (Large); 16-30 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3 (cohort)<br/></td>\n\n</tr>\n</table><p>These sphinxes are always male. Neither good nor evil, they lack the intelligence of the androsphinx.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Criosphinxes attack with their claws, as do their kin, but they can also butt with their horns. They don\'t cast spells and employ only the most simple battle tactics.</p><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +15 melee, damage 1d6+3.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (567,'Sphinx','Gynosphinx',NULL,'Large','Magical Beast',NULL,'8d10+8 (52 hp)','+5','40 ft. (8 squares), fly 60 ft. (poor)','21 (-1 size, +1 Dex, +11 natural), touch 10, flat-footed 20','+8','+16','Claw +11 melee (1d6+4)','2 claws +11 melee (1d6+4)','10 ft.','5 ft.','Pounce, rake 1d6+2, spell-like abilities','Darkvision 60 ft., low-light vision','Fort +7, Ref +7, Will +8','Str 19, Dex 12, Con 13, Int 18, Wis 19, Cha 19','Bluff +15, Concentration +12, Diplomacy +8, Disguise +4 (+6 acting), Intimidate +13, Listen +17, Sense Motive +15, Spot +17',NULL,'Combat Casting, Improved Initiative, Iron Will',NULL,'Warm deserts','Solitary or covey (2-4)','8','Double standard','Always neutral','9-12 HD (Large); 13-24 HD (Huge)','+4 (cohort)','Pounce (Ex), Rake (Ex)','Gynosphinx; CR 8; Large magical beast; HD 8d10+8; hp 52; Init +5; Spd 40 ft. (8 squares), fly 60 ft. (poor); AC 21 (-1 size, +1 dex, +11 natural), touch 10, flat-footed 20; Base Atk +8; Grp +16; Atk +11 melee (1d6+4, claw); Full Atk +11 melee (1d6+4, 2 claws); Space/Reach 10 ft./5 ft.; SA Pounce, rake 1d6+2, spell-like abilities; SQ Darkvision 60 ft., low-light vision; AL N; SV Fort +7, Ref +7, Will +8; Str 19, Dex 12, Con 13, Int 18, Wis 19, Cha 19\n\nSkills and Feats: Bluff +15, Concentration +12, Diplomacy +8, Disguise +4 (+6 acting), Intimidate +13, Listen +17, Sense Motive +15, Spot +17; Combat Casting, Improved Initiative, Iron Will','\n      <div topic=\"Gynosphinx\" level=\"3\"><p><h3>Gynosphinx</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Gynosphinx</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>8d10+8 (52 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares), fly 60 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>21 (-1 size, +1 Dex, +11 natural), touch 10, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+8/+16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +11 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +11 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Pounce, rake 1d6+2, spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +7, Ref +7, Will +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 19, Dex 12, Con 13, Int 18, Wis 19, Cha 19<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +15, Concentration +12, Diplomacy +8, Disguise +4 (+6 acting), Intimidate +13, Listen +17, Sense Motive +15, Spot +17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Combat Casting, Improved Initiative, Iron Will<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or covey (2-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Double standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>9-12 HD (Large); 13-24 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4 (cohort)<br/></td>\n\n</tr>\n</table><p>These sphinxes are the female counterparts of androsphinxes.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>In close combat, gynosphinxes use their powerful claws to flay the flesh from their enemies. Despite their deadly nature, they prefer to avoid combat whenever possible.</p><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +11 melee, damage 1d6+2.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 3/day-<i>clairaudience/clairvoyance</i>,  <i>detect magic</i>,  <i>read magic</i>,  <i>see invisibility</i>; 1/day-<i>comprehend languages</i>,  <i>locate object</i>,  <i>dispel magic</i>,  <i>remove curse</i> (DC 18), <i>legend lore</i>. Caster level 14th. The save DC is Charisma-based.</p><p>Once per week a gynosphinx can create a <i>symbol of death</i>,  a <i>symbol of fear</i>,  a <i>symbol of insanity</i>,  a <i>symbol of pain</i>,  a <i>symbol of persuasion</i>,  a <i>symbol of sleep</i>,  and a <i>symbol of stunning</i> as the spells (caster level 18th), except that all save DCs are 22 and each symbol remains a maximum of one week once scribed. The save DCs are Charisma-based.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (568,'Sphinx','Hieracosphinx',NULL,'Large','Magical Beast',NULL,'9d10+18 (67 hp)','+2','30 ft. (6 squares), fly 90 ft. (poor)','19 (-1 size, +2 Dex, +8 natural), touch 11, flat-footed 17','+9','+18','Bite +13 melee (1d10+5)','Bite +13 melee (1d10+5) and 2 claws +8 melee (1d6+2)','10 ft.','5 ft.','Pounce, rake 1d6+2','Darkvision 60 ft., low-light vision','Fort +8, Ref +8, Will +5','Str 21, Dex 14, Con 15, Int 6, Wis 15, Cha 10','Listen +10, Spot +14',NULL,'Alertness, Cleave, Flyby Attack, Power Attack',NULL,'Warm deserts','Solitary, pair, or flock (4-7)','5','None','Always chaotic evil','10-14 HD (Large); 15-27 HD (Huge)','+3 (cohort)','Pounce (Ex), Rake (Ex)','Hieracosphinx; CR 5; Large magical beast; HD 9d10+18; hp 67; Init +2; Spd 30 ft. (6 squares), fly 90 ft. (poor); AC 19 (-1 size, +2 dex, +8 natural), touch 11, flat-footed 17; Base Atk +9; Grp +18; Atk +13 melee (1d10+5, bite); Full Atk +13 melee (1d10+5, bite) and +8 melee (1d6+2, 2 claws); Space/Reach 10 ft./5 ft.; SA Pounce, rake 1d6+2; SQ Darkvision 60 ft., low-light vision; AL CE; SV Fort +8, Ref +8, Will +5; Str 21, Dex 14, Con 15, Int 6, Wis 15, Cha 10\n\nSkills and Feats: Listen +10, Spot +14; Alertness, Cleave, Flyby Attack, Power Attack','\n      <div topic=\"Hieracosphinx\" level=\"3\"><p><h3>Hieracosphinx</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Hieracosphinx</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d10+18 (67 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), fly 90 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>19 (-1 size, +2 Dex, +8 natural), touch 11, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +13 melee (1d10+5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +13 melee (1d10+5) and 2 claws +8 melee (1d6+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Pounce, rake 1d6+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +8, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 21, Dex 14, Con 15, Int 6, Wis 15, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +10, Spot +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Cleave, Flyby Attack, Power Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or flock (4-7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-14 HD (Large); 15-27 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3 (cohort)<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Hieracosphinxes can make short work of even the most dangerous opponents with their claws. They are not particularly intelligent, but are cunning enough to dive at their enemies from above with their flying ability.</p><div topic=\"Rake\" level=\"8\"><p><b>Rake (Ex):</b> Attack bonus +13 melee, damage 1d6+2.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Hieracosphinxes have a +4 racial bonus on Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (569,'Spider Eater','Spider Eater',NULL,'Large','Magical Beast',NULL,'4d10+20 (42 hp)','+1','30 ft. (6 squares), fly 60 ft. (good)','14 (-1 size, +1 Dex, +4 natural), touch 10, flat-footed 13','+4','+13','Sting +8 melee (1d8+5 plus poison)','Sting +8 melee (1d8+5 plus poison) and bite +3 melee (1d8+2)','10 ft.','5 ft.','Implant, poison','Darkvision 60 ft., freedom of movement, low-light vision, scent','Fort +9, Ref +5, Will +2','Str 21, Dex 13, Con 21, Int 2, Wis 12, Cha 10','Listen +10, Spot +11',NULL,'Alertness, Dodge',NULL,'Temperate forests','Solitary','5','None','Always neutral','5-12 HD (Huge)','-','Freedom of Movement (Su), Implant (Ex), Poison (Ex)','Spider eater; CR 5; Large magical beast; HD 4d10+20; hp 42; Init +1; Spd 30 ft. (6 squares), fly 60 ft. (good); AC 14 (-1 size, +1 dex, +4 natural), touch 10, flat-footed 13; Base Atk +4; Grp +13; Atk +8 melee (1d8+5 plus poison, sting); Full Atk +8 melee (1d8+5 plus poison, sting) and +3 melee (1d8+2, bite); Space/Reach 10 ft./5 ft.; SA Implant, poison; SQ Darkvision 60 ft., freedom of movement, low-light vision, scent; AL N; SV Fort +9, Ref +5, Will +2; Str 21, Dex 13, Con 21, Int 2, Wis 12, Cha 10\n\nSkills and Feats: Listen +10, Spot +11; Alertness, Dodge','\n      <div topic=\"Spider Eater\" level=\"2\"><p><h2>Spider Eater</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Spider Eater</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d10+20 (42 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (-1 size, +1 Dex, +4 natural), touch 10, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Sting +8 melee (1d8+5 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Sting +8 melee (1d8+5 plus poison) and bite +3 melee (1d8+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Implant, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., freedom of movement, low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +9, Ref +5, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 21, Dex 13, Con 21, Int 2, Wis 12, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +10, Spot +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Dodge<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-12 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A spider eater is about 10 feet long and 4 feet high, and has a wingspan of about 20 feet. It weighs about 4,000 pounds.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A spider eater attacks with its venomous sting and powerful mandibles. Its usual tactic is to deliver a sting, then back off, hovering out of reach until the venom takes effect.</p><div topic=\"Implant\" level=\"8\"><p><b>Implant (Ex):</b> Female spider eaters lay their eggs inside paralyzed creatures of Large or larger size. The young emerge about six weeks later, literally devouring the host from inside.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 17, initial damage none, secondary damage paralysis for 1d8+5 weeks. The save DC is Constitution-based.</p>\n</div><div topic=\"Freedom of Movement\" level=\"8\"><p><b>Freedom of Movement (Su):</b> Spider eaters have a continuous freedom of movement ability as the spell (caster level 12th). When the spider eater serves as a mount, this effect does not extend to its rider.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Spider eaters have a +4 racial bonus on Listen and Spot checks.</p>\n</div>\n</div><div topic=\"Training A Spider Eater\" level=\"3\"><p><h3>Training A Spider Eater</h3></p><p>A spider eater requires training before it can bear a rider in combat.</p><p>Training a spider eater requires six weeks of work and a DC 25 Handle Animal check. Riding a spider eater requires an exotic saddle. A spider eater can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check.</p><p>Spider eater eggs are worth 2,000 gp apiece on the open market, while young are worth 3,000 gp each. Professional trainers charge 3,000 gp to rear or train a spider eater.</p><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a spider eater is up to 306 pounds; a medium load, 307-612 pounds; and a heavy load, 613-920 pounds.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (570,'Sprite','Grig',NULL,'Tiny','Fey',NULL,'1/2 d6+1 (2 hp)','+4','20 ft. (4 squares), fly 40 ft. (poor)','18 (+2 size, +4 Dex, +2 natural), touch 16, flat-footed 16','+0','-11','Short sword +6 melee (1d3-3/19-20) or longbow +6 ranged (1d4-3/x3)','Short sword +6 melee (1d3-3/19-20) or longbow +6 ranged (1d4-3/x3)','2-1/2 ft.','0 ft.','Spell-like abilities, fiddle','Damage reduction 5/cold iron, low-light vision, spell resistance 17','Fort +1, Ref +6, Will +3','Str 5, Dex 18, Con 13, Int 10, Wis 13, Cha 14','Craft (any one) +4, Escape Artist +8, Hide +16, Jump +3, Listen +3, Move Silently +8*, Perform (string instruments) +6, Search +2, Spot +3','Dodge','Weapon Finesse',NULL,'Temperate forests','Gang (2-4), band (6-11), or tribe (20-80)','1','No coins; 50% goods; 50% items','Always neutral good','1-3 HD (Tiny)','+3','Fiddle (Su)','Grig; CR 1; Tiny fey; HD 1/2 d6+1; hp 2; Init +4; Spd 20 ft. (4 squares), fly 40 ft. (poor); AC 18 (+2 size, +4 dex, +2 natural), touch 16, flat-footed 16; Base Atk +0; Grp -11; Atk +6 melee (1d3-3/19-20, short sword) or +6 ranged (1d4-3/x3, longbow); Full Atk +6 melee (1d3-3/19-20, short sword) or +6 ranged (1d4-3/x3, longbow); Space/Reach 2-1/2 ft./0 ft.; SA Spell-like abilities, fiddle; SQ Damage reduction 5/cold iron, low-light vision, spell resistance 17; AL NG; SV Fort +1, Ref +6, Will +3; Str 5, Dex 18, Con 13, Int 10, Wis 13, Cha 14\n\nSkills and Feats: Craft (any one) +4, Escape Artist +8, Hide +16, Jump +3, Listen +3, Move Silently +8*, Perform (string instruments) +6, Search +2, Spot +3; Dodge, Weapon Finesse','\n      <div topic=\"Grig\" level=\"3\"><p><h3>Grig</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Grig</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Fey<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1/2 d6+1 (2 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 40 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+2 size, +4 Dex, +2 natural), touch 16, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Short sword +6 melee (1d3-3/19-20) or longbow +6 ranged (1d4-3/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Short sword +6 melee (1d3-3/19-20) or longbow +6 ranged (1d4-3/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Spell-like abilities, fiddle<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 5/cold iron, low-light vision, spell resistance 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +6, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 5, Dex 18, Con 13, Int 10, Wis 13, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Craft (any one) +4, Escape Artist +8, Hide +16, Jump +3, Listen +3, Move Silently +8*, Perform (string instruments) +6, Search +2, Spot +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Dodge <sup>B</sup>, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Gang (2-4), band (6-11), or tribe (20-80)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>No coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>1-3 HD (Tiny)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n</table><p>Grigs can leap great distances. They have light blue skin, forest-green hair, and brown hairy legs, and usually wear tunics or brightly colored vests with buttons made from tiny gems. A grig stands 1-1/2 feet tall and weighs about 1 pound.</p><p>Grigs speak Sylvan. Some also speak Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Grigs are fierce by sprite standards, attacking opponents fearlessly with bow and dagger.</p><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 3/day-<i>disguise self</i>,  <i>entangle</i> (DC 13),  <i>invisibility</i> (self only), <i>pyrotechnics</i> (DC 14),  <i>ventriloquism</i> (DC 13). Caster level 9th. The save DCs are Charisma-based.</p>\n</div><div topic=\"Fiddle\" level=\"8\"><p><b>Fiddle (Su):</b> One grig in each band carries a tiny, grig-sized fiddle. When the fiddler plays, any nonsprite within 30 feet of the instrument must succeed on a DC 12 Will save or be affected as though by <i>irresistible dance</i> for as long as the playing continues. The save DC is Charisma-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Grigs have a +8 racial bonus on Jump checks. *They also have a +5 racial bonus on Move Silently checks in a forest setting.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (571,'Sprite','Nixie',NULL,'Small','Fey','Aquatic','1d6 (3 hp)','+3','20 ft. (4 squares), swim 30 ft.','14 (+1 size, +3 Dex), touch 14, flat-footed 11','+0','-6','Short sword +4 melee (1d4-2/19-20) or light crossbow +4 ranged (1d6/19-20)','Short sword +4 melee (1d4-2/19-20) or light crossbow +4 ranged (1d6/19-20)','5 ft.','5 ft.','Charm person','Amphibious, damage reduction 5/cold iron, low-light vision, spell resistance 16, water breathing, wild empathy','Fort +0, Ref +5, Will +3','Str 7, Dex 16, Con 11, Int 12, Wis 13, Cha 18','Bluff +8, Craft (any one) +5, Escape Artist +6, Handle Animal +8, Hide +7*, Listen +6, Perform (sing) +7, Search +3, Sense Motive +5, Spot +6, Swim +6','Dodge','Weapon Finesse',NULL,'Temperate aquatic','Gang (2-4), band (6-11), or tribe (20-80)','1','No coins; 50% goods (metal or stone only); 50% items (no scrolls)','Always neutral','2-3 HD (Small)','+3','Amphibious (Ex), Charm Person (Sp), Water Breathing (Sp), Wild Empathy (Ex)','Nixie; CR 1; Small fey (aquatic); HD 1d6; hp 3; Init +3; Spd 20 ft. (4 squares), swim 30 ft.; AC 14 (+1 size, +3 dex), touch 14, flat-footed 11; Base Atk +0; Grp -6; Atk +4 melee (1d4-2/19-20, short sword) or +4 ranged (1d6/19-20, light crossbow); Full Atk +4 melee (1d4-2/19-20, short sword) or +4 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Charm person; SQ Amphibious, damage reduction 5/cold iron, low-light vision, spell resistance 16, water breathing,  wild empathy; AL N; SV Fort +0, Ref +5, Will +3; Str 7, Dex 16, Con 11, Int 12, Wis 13, Cha 18\n\nSkills and Feats: Bluff +8, Craft (any one) +5, Escape Artist +6, Handle Animal +8, Hide +7*, Listen +6, Perform (sing) +7, Search +3, Sense Motive +5, Spot +6, Swim +6; Dodge, Weapon Finesse','\n      <div topic=\"Nixie\" level=\"3\"><p><h3>Nixie</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Nixie</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Fey (Aquatic)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d6 (3 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), swim 30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+1 size, +3 Dex), touch 14, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Short sword +4 melee (1d4-2/19-20) or light crossbow +4 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Short sword +4 melee (1d4-2/19-20) or light crossbow +4 ranged (1d6/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td><i>Charm person</i><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Amphibious, damage reduction 5/cold iron, low-light vision, spell resistance 16, <i>water breathing</i>,  wild empathy<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +5, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 7, Dex 16, Con 11, Int 12, Wis 13, Cha 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +8, Craft (any one) +5, Escape Artist +6, Handle Animal +8, Hide +7*, Listen +6, Perform (sing) +7, Search +3, Sense Motive +5, Spot +6, Swim +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Dodge <sup>B</sup>, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Gang (2-4), band (6-11), or tribe (20-80)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>No coins; 50% goods (metal or stone only); 50% items (no scrolls)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>2-3 HD (Small)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n</table><p>Most nixies are slim and comely, with lightly scaled, pale green skin and dark green hair. Females often twine shells and pearl strings in their hair and dress in wraps woven from colorful seaweed. Males wear loincloths of the same materials. Nixies prefer not to leave their lakes.</p><p>A nixie stands about 4 feet tall and weighs about 45 pounds.</p><p>Nixies speak Aquan and Sylvan. Some also speak Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Nixies rely on their <i>Charm Person</i> ability to deter enemies, entering combat only to protect themselves and their territory.</p><div topic=\"Charm Person\" level=\"8\"><p><b><i>Charm Person</i> (Sp):</b> A nixie can use <i>Charm Person</i> three times per day as the spell (caster level 4th). Those affected must succeed on a DC 15 Will save or be <i>charmed</i> for 24 hours. Most <i>charmed</i> creatures are used to perform heavy labor, guard duty, and other onerous tasks for the nixie community. Shortly before the effect wears off, the nixie escorts the <i>charmed</i> creature away and orders it to keep walking. The save DC is Charisma-based.</p>\n</div><div topic=\"Amphibious\" level=\"8\"><p><b>Amphibious (Ex):</b> Although nixies are aquatic, they can survive indefinitely on land.</p>\n</div><div topic=\"Water Breathing\" level=\"8\"><p><b><i>water breathing</i> (Sp):</b> Once per day a nixie can use <i>water breathing</i> as the spell (caster level 12th). Nixies usually bestow this effect on those they have <i>charmed</i>.</p>\n</div><div topic=\"Wild Empathy\" level=\"8\"><p><b>Wild Empathy (Ex):</b> This ability works like the druid\'s wild empathy class feature, except that a nixie has a +6 racial bonus on the check.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A nixie has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line. *Nixies have a +5 racial bonus on Hide checks when in the water.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (572,'Sprite','Pixie',NULL,'Small','Fey',NULL,'1d6 (3 hp)','+4','20 ft. (4 squares), fly 60 ft. (good)','16 (+1 size, +4 Dex, +1 natural), touch 15, flat-footed 12','+0','-6','Short sword +5 melee (1d4-2/19-20) or longbow +5 ranged (1d6-2/3)','Short sword +5 melee (1d4-2/19-20) or longbow +5 ranged (1d6-2)/x3','5 ft.','5 ft.','Spell-like abilities, special arrows','Damage reduction 10/cold iron, greater invisibility, low-light vision, spell resistance 15','Fort +0, Ref +6, Will +4','Str 7, Dex 18, Con 11, Int 16, Wis 15, Cha 16','Bluff +7, Concentration +4, Escape Artist +8, Hide +8, Listen +8, Move Silently +8, Ride +8, Search +9, Sense Motive +6, Spot +8','Dodge','Weapon Finesse',NULL,'Temperate forests','Gang (2-4), band (6-11), or tribe (20-80)','4 (5 with irresistible dance)','No coins; 50% goods; 50% items','Always neutral good','2-3 HD (Small)','+4 (+6 with irresistible dance)','Greater Invisibility (Su), Special Arrows (Ex)','Pixie; CR 4 (5 with irresistible dance); Small fey; HD 1d6; hp 3; Init +4; Spd 20 ft. (4 squares), fly 60 ft. (good); AC 16 (+1 size, +4 dex, +1 natural), touch 15, flat-footed 12; Base Atk +0; Grp -6; Atk +5 melee (1d4-2/19-20, short sword) or +5 ranged (1d6-2/3, longbow); Full Atk +5 melee (1d4-2/19-20, short sword) or +5 /x3 ranged (1d6-2, longbow); Space/Reach 5 ft./5 ft.; SA Spell-like abilities, special arrows; SQ Damage reduction 10/cold iron, greater invisibility, low-light vision, spell resistance 15; AL NG; SV Fort +0, Ref +6, Will +4; Str 7, Dex 18, Con 11, Int 16, Wis 15, Cha 16\n\nSkills and Feats: Bluff +7, Concentration +4, Escape Artist +8, Hide +8, Listen +8, Move Silently +8, Ride +8, Search +9, Sense Motive +6, Spot +8; Dodge, Weapon Finesse','\n      <div topic=\"Pixie\" level=\"3\"><p><h3>Pixie</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Pixie</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Fey<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d6 (3 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 60 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+1 size, +4 Dex, +1 natural), touch 15, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+0/-6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Short sword +5 melee (1d4-2/19-20) or longbow +5 ranged (1d6-2/3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Short sword +5 melee (1d4-2/19-20) or longbow +5 ranged (1d6-2)/x3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Spell-like abilities, special arrows<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 10/cold iron, greater invisibility, low-light vision, spell resistance 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +6, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 7, Dex 18, Con 11, Int 16, Wis 15, Cha 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +7, Concentration +4, Escape Artist +8, Hide +8, Listen +8, Move Silently +8, Ride +8, Search +9, Sense Motive +6, Spot +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Dodge <sup>B</sup>, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Gang (2-4), band (6-11), or tribe (20-80)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>4 (5 with <i>irresistible dance</i>)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>No coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>2-3 HD (Small)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4 (+6 with <i>irresistible dance</i>)<br/></td>\n\n</tr>\n</table><p>Pixies wear bright clothing, often including a cap and shoes with curled and pointed toes.</p><p>A pixie stands about 2-1/2 feet tall and weighs about 30 pounds.</p><p>Pixies speak Sylvan and Common, and may know other languages as well.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>The normally carefree pixies ferociously attack evil creatures and unwanted intruders. They take full advantage of their invisibility and other abilities to harass and drive away opponents.</p><div topic=\"Greater Invisibility\" level=\"8\"><p><b>Greater Invisibility (Su):</b> A pixie remains invisible even when it attacks. This ability is constant, but the pixie can suppress or resume it as a free action.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 1/day-<i>lesser confusion</i> (DC 14), <i>dancing lights</i>,  <i>detect chaos</i>,  <i>detect good</i>,  <i>detect evil</i>,  <i>detect law</i>,  <i>detect thoughts</i> (DC 15), <i>dispel magic</i>,  <i>entangle</i> (DC 14), <i>permanent image</i> (DC 19; visual and auditory elements only), <i>polymorph</i> (self only). Caster level 8th. The save DCs are Charisma-based.</p><p>One pixie in ten can use <i>irresistible dance</i> (caster level 8th) once per day.</p>\n</div><div topic=\"Special Arrows\" level=\"8\"><p><b>Special Arrows (Ex):</b> Pixies sometimes employ arrows that deal no damage but can erase memory or put a creature to sleep.</p><p><i>Memory Loss:</i> An opponent struck by this arrow must succeed on a DC 15 Will save or lose all memory. The save DC is Charisma-based and includes a +2 racial bonus. The subject retains skills, languages, and class abilities but forgets everything else until he or she receives a <i>heal</i> spell or memory restoration with <i>limited wish</i>,  <i>wish</i>,  or <i>miracle</i>.</p><p><i>Sleep:</i> Any opponent struck by this arrow, regardless of Hit Dice, must succeed on a DC 15 Fortitude save or be affected as though by a <i>sleep</i> spell. The save DC is Charisma-based and includes a +2 racial bonus.</p>\n</div>\n</div><div topic=\"Pixies as Characters\" level=\"5\"><p><h5>Pixies as Characters</h5></p><p>A pixie character exchanges its 1 HD of fey for its first class level.</p><p>Pixie characters possess the following racial traits.</p><ul>\n <li>-4 Strength, +8 Dexterity, +6 Intelligence, +4 Wisdom, +6 Charisma.</li>\n <li>Small size. +1 bonus to Armor Class, +1 bonus on attack rolls, +4 bonus on Hide checks, -4 penalty on grapple checks, lifting and carrying limits 3/4 those of Medium characters.</li>\n</ul><p>-A pixie\'s base land speed is 20 feet. It also has a fly speed of 60 feet (good).</p><ul>\n <li>Low-light vision.</li>\n <li>Skills: Pixies have a +2 racial bonus on Listen, Search, and Spot checks.</li>\n <li>Racial Feats: A pixie receives Dodge as a bonus feat.</li>\n <li>+1 natural armor bonus.</li>\n <li>Special Attacks (see above): Spell-like abilities.</li>\n <li>Special Qualities (see above): Damage reduction 10/cold iron, greater invisibility, spell resistance equal to 15 + class levels.</li>\n <li>Automatic Languages: Common, Sylvan. Bonus Languages: Elven, Gnome, Halfling.</li>\n <li>Favored Class: Sorcerer.</li>\n <li>Level adjustment +4 (+6 if the pixie can use <i>irresistible dance)</i>.</li>\n</ul><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (573,'Stirge','Stirge',NULL,'Tiny','Magical Beast',NULL,'1d10 (5 hp)','+4','10 ft (2 squares), fly 40 ft. (average)','16 (+2 size, +4 Dex), touch 16, flat-footed 12','+1','-11 (+1 when attached)','Touch +7 melee (attach)','Touch +7 melee (attach)','2-1/2 ft.','0 ft.','Attach, blood drain','Darkvision 60 ft., low-light vision','Fort +2, Ref +6, Will +1','Str 3, Dex 19, Con 10, Int 1, Wis 12, Cha 6','Hide +14, Listen +4, Spot +4','Weapon Finesse','Alertness',NULL,'Warm marshes','Colony (2-4), flock (5-8), or storm (9-14)','1/2','None','Always neutral','-','-','Attach (Ex), Blood Drain (Ex)','Stirge; CR 1/2; Tiny magical beast; HD 1d10; hp 5; Init +4; Spd 10 ft (2 squares), fly 40 ft. (average); AC 16 (+2 size, +4 dex), touch 16, flat-footed 12; Base Atk +1; Grp -11 (+1 when attached); Atk +7 melee (attach, touch); Full Atk +7 melee (attach, touch); Space/Reach 2-1/2 ft./0 ft.; SA Attach, blood drain; SQ Darkvision 60 ft., low-light vision; AL N; SV Fort +2, Ref +6, Will +1; Str 3, Dex 19, Con 10, Int 1, Wis 12, Cha 6\n\nSkills and Feats: Hide +14, Listen +4, Spot +4; Alertness, Weapon Finesse','\n      <div topic=\"Stirge\" level=\"2\"><p><h2>Stirge</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Stirge</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d10 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft (2 squares), fly 40 ft. (average)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+2 size, +4 Dex), touch 16, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-11 (+1 when attached)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Touch +7 melee (attach)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Touch +7 melee (attach)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>2-1/2 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Attach, blood drain<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +2, Ref +6, Will +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 3, Dex 19, Con 10, Int 1, Wis 12, Cha 6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +14, Listen +4, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm marshes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Colony (2-4), flock (5-8), or storm (9-14)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1/2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A stirge\'s coloration ranges from rust-red to reddish-brown, with a dirty yellow underside. The proboscis is pink at the tip, fading to gray at its base.</p><p>A stirge\'s body is about 1 foot long, with a wingspan of about 2 feet. It weighs about 1 pound.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A stirge attacks by landing on a victim, finding a vulnerable spot, and plunging its proboscis into the flesh. This is a touch attack and can target only Small or larger creatures.</p><div topic=\"Attach\" level=\"8\"><p><b>Attach (Ex):</b> If a stirge hits with a touch attack, it uses its eight pincers to latch onto the opponent\'s body. An attached stirge is effectively grappling its prey. The stirge loses its Dexterity bonus to AC and has an AC of 12, but holds on with great tenacity. Stirges have a +12 racial bonus on grapple checks (already figured into the Base Attack/Grapple entry above).</p><p>An attached stirge can be struck with a weapon or grappled itself. To remove an attached stirge through grappling, the opponent must achieve a pin against the stirge.</p>\n</div><div topic=\"Blood Drain\" level=\"8\"><p><b>Blood Drain (Ex):</b> A stirge drains blood, dealing 1d4 points of Constitution damage in any round when it begins its turn attached to a victim. Once it has dealt 4 points of Constitution damage, it detaches and flies off to digest the meal. If its victim dies before the stirge\'s appetite has been sated, the stirge detaches and seeks a new target.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (574,'Swarm','Bat Swarm',NULL,'Diminutive','Animal','Swarm','3d8 (13 hp)','+2','5 ft. (1 square), fly 40 ft. (good)','16 (+4 size, +2 Dex), touch 14, flat-footed 12','+2','-','Swarm (1d6)','Swarm (1d6)','10 ft.','0 ft.','Distraction, wounding','Blindsense 20 ft., half damage from slashing and piercing, low-light vision, swarm traits','Fort +3, Ref +7, Will +3','Str 3, Dex 15, Con 10, Int 2, Wis 14, Cha 4','Listen +11, Spot +11',NULL,'Alertness, Lightning Reflexes',NULL,'Temperate deserts','Solitary, flight (2-4 swarms), or colony (11-20 swarms)','2','None','Always neutral','None','-','Blindsense (Ex), Distraction (Ex), Wounding (Ex)','Bat swarm; CR 2; Diminutive animal (swarm); HD 3d8; hp 13; Init +2; Spd 5 ft. (1 square), fly 40 ft. (good); AC 16 (+4 size, +2 dex), touch 14, flat-footed 12; Base Atk +2; Grp -; Atk Swarm (1d6); Full Atk Swarm (1d6); Space/Reach 10 ft./0 ft.; SA Distraction, wounding; SQ Blindsense 20 ft., half damage from slashing and piercing, low-light vision, swarm traits; AL N; SV Fort +3, Ref +7, Will +3; Str 3, Dex 15, Con 10, Int 2, Wis 14, Cha 4\n\nSkills and Feats: Listen +11, Spot +11; Alertness, Lightning Reflexes','\n      <div topic=\"Bat Swarm\" level=\"3\"><p><h3>Bat Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Bat Swarm</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Animal (Swarm)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8 (13 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>5 ft. (1 square), fly 40 ft. (good)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+4 size, +2 Dex), touch 14, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Swarm (1d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Swarm (1d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Distraction, wounding<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Blindsense 20 ft., half damage from slashing and piercing, low-light vision, swarm traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 3, Dex 15, Con 10, Int 2, Wis 14, Cha 4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +11, Spot +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Lightning Reflexes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, flight (2-4 swarms), or colony (11-20 swarms)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A bat swarm is nocturnal, and is never found aboveground in daylight.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A bat swarm seeks to surround and attack any warm-blooded prey it encounters. The swarm deals 1d6 points of damage to any creature whose space it occupies at the end of its move.</p><div topic=\"Distraction\" level=\"8\"><p><b>Distraction (Ex):</b> Any living creature that begins its turn with a swarm in its space must succeed on a DC 11 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based.</p>\n</div><div topic=\"Wounding\" level=\"8\"><p><b>Wounding (Ex):</b> Any living creature damaged by a bat swarm continues to bleed, losing 1 hit point per round thereafter. Multiple wounds do not result in cumulative bleeding loss. The bleeding can be stopped by a DC 10 Heal check or the application of a <i>cure</i> spell or some other healing magic.</p>\n</div><div topic=\"Blindsense\" level=\"8\"><p><b>Blindsense (Ex):</b> A bat swarm notices and locates creatures within 20 feet. Opponents still have total concealment against the bat swarm (but swarm attacks ignore concealment).</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A bat swarm has a +4 racial bonus on Listen and Spot checks. These bonuses are lost if its blindsense is negated.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (575,'Swarm','Centipede Swarm',NULL,'Diminutive','Vermin','Swarm','9d8-9 (31 hp)','+4','20 ft. (4 squares), climb 20 ft.','18 (+4 size, +4 Dex), touch 18, flat-footed 14','+6','-','Swarm (2d6 plus poison)','Swarm (2d6 plus poison)','10 ft.','0 ft.','Distraction, poison','Darkvision 60 ft., immune to weapon damage, swarm traits, tremorsense 30 ft., vermin traits','Fort +5, Ref +7, Will +3','Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2','Climb +12, Spot +4','Weapon Finesse',NULL,NULL,'Underground','Solitary, tangle (2-4 swarms), or colony (7-12 swarms)','4','None','Always neutral','None','-','Distraction (Ex), Poison (Ex)','Centipede swarm; CR 4; Diminutive vermin (swarm); HD 9d8-9; hp 31; Init +4; Spd 20 ft. (4 squares), climb 20 ft.; AC 18 (+4 size, +4 dex), touch 18, flat-footed 14; Base Atk +6; Grp -; Atk Swarm (2d6 plus poison); Full Atk Swarm (2d6 plus poison); Space/Reach 10 ft./0 ft.; SA Distraction, poison; SQ Darkvision 60 ft., immune to weapon damage, swarm traits, tremorsense 30 ft., vermin traits; AL N; SV Fort +5, Ref +7, Will +3; Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2\n\nSkills and Feats: Climb +12, Spot +4; Weapon Finesse','\n      <div topic=\"Centipede Swarm\" level=\"3\"><p><h3>Centipede Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Centipede Swarm</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Vermin (Swarm)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d8-9 (31 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), climb 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+4 size, +4 Dex), touch 18, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Swarm (2d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Swarm (2d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Distraction, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immune to weapon damage, swarm traits, tremorsense 30 ft., vermin traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +12, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, tangle (2-4 swarms), or colony (7-12 swarms)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A centipede swarm seeks to surround and attack any living prey it encounters. A swarm deals 2d6 points of damage to any creature whose space it occupies at the end of its move.</p><div topic=\"Distraction\" level=\"8\"><p><b>Distraction (Ex):</b> Any living creature that begins its turn with a centipede swarm in its space must succeed on a DC 13 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 13, initial and secondary damage 1d4 Dex. The save DC is Constitution-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A centipede swarm has a +4 racial bonus on Spot checks and a +8 racial bonus on Climb checks, and uses its Dexterity modifier instead of its Strength modifier for Climb checks. A centipede swarm has a +8 racial bonus on Climb checks and can always choose to take 10 on a Climb check, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (576,'Swarm','Hellwasp Swarm',NULL,'Diminutive','Magical Beast','Extraplanar, Evil, Swarm','12d10+27 (93 hp)','+10','5 ft. (1 square), fly 40 ft.','20 (+4 size, +6 Dex), touch 20, flat-footed 14','+12','-','Swarm (3d6 plus poison)','Swarm (3d6 plus poison)','10 ft.','0 ft.','Distraction, inhabit, poison','Damage reduction 10/magic, darkvision 60 ft., hive mind, immune to weapon damage, fire resistance 10, low-light vision, swarm traits','Fort +10, Ref +14, Will +7','Str 1, Dex 22, Con 14, Int 6, Wis 13, Cha 9','Hide +19, Listen +10, Spot +10',NULL,'Ability Focus (poison), Alertness, Improved Initiative, Iron Will, Toughness',NULL,'A evil-aligned plane','Solitary, fright (2-4 swarms), or terror (5-8 swarms)','8','None','Always lawful evil','None','-','Distraction (Ex), Hive Mind (Ex), Inhabit (Ex), Poison (Ex)','Hellwasp swarm; CR 8; Diminutive magical beast (extraplanar, evil, swarm); HD 12d10+27; hp 93; Init +10; Spd 5 ft. (1 square), fly 40 ft.; AC 20 (+4 size, +6 dex), touch 20, flat-footed 14; Base Atk +12; Grp -; Atk Swarm (3d6 plus poison); Full Atk Swarm (3d6 plus poison); Space/Reach 10 ft./0 ft.; SA Distraction, inhabit, poison; SQ Damage reduction 10/magic, darkvision 60 ft., hive mind, immune to weapon damage, fire resistance 10, low-light vision, swarm traits; AL LE; SV Fort +10, Ref +14, Will +7; Str 1, Dex 22, Con 14, Int 6, Wis 13, Cha 9\n\nSkills and Feats: Hide +19, Listen +10, Spot +10; Ability Focus (poison), Alertness, Improved Initiative, Iron Will, Toughness','\n      <div topic=\"Hellwasp Swarm\" level=\"3\"><p><h3>Hellwasp Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Hellwasp Swarm</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Magical Beast (Extraplanar, Evil, Swarm)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d10+27 (93 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>5 ft. (1 square), fly 40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (+4 size, +6 Dex), touch 20, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+12/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Swarm (3d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Swarm (3d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Distraction, inhabit, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 10/magic, darkvision 60 ft., hive mind, immune to weapon damage, fire resistance 10, low-light vision, swarm traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +10, Ref +14, Will +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 22, Con 14, Int 6, Wis 13, Cha 9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +19, Listen +10, Spot +10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Ability Focus (poison), Alertness, Improved Initiative, Iron Will, Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>A evil-aligned plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, fright (2-4 swarms), or terror (5-8 swarms)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A single hellwasp resembles a thumb-sized normal wasp, except its carapace is gleaming black with ruby-red stripes, and its compound eyes are an iridescent green. In swarms, hellwasps form a collective hive mind intelligence with infernal cunning and bloodlust.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Like any swarm, a hellwasp swarm seeks to surround and attack any living prey it encounters. A swarm deals 3d6 points of damage to any creature whose space it occupies at the end of its move. The swarm can take over the bodies of its prey and infest both the living and the dead, using them as horrible living (or unliving) puppets to accomplish acts of wickedness that a swarm of insects could never attempt.</p><p>A hellwasp swarm\'s attack is treated as an evil-aligned weapon and a magic weapon for the purpose of overcoming damage reduction.</p><div topic=\"Distraction\" level=\"8\"><p><b>Distraction (Ex):</b> Any living creature that begins its turn with a hellwasp swarm in its space must succeed on a DC 18 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based.</p>\n</div><div topic=\"Inhabit\" level=\"8\"><p><b>Inhabit (Ex):</b> A hellwasp swarm can enter the body of a helpless or dead creature by crawling into its mouth and other orifices. Inhabiting requires 1 minute, and the victim must be Small, Medium, or Large (although four swarms working together can  inhabit a Huge creature). The swarm can abandon the body at any time, although doing this takes 1 full round. Any attack against the host deals half damage to the hellwasp swarm as well, although the swarm\'s resistances and immunities may negate some or all of this damage.</p><p>If a hellwasp swarm inhabits a dead body, it can restore animation to the creature and control its movements, effectively transforming it into a zombie of the appropriate size for as long as the swarm remains inside. If a hellwasp swarm inhabits a living victim, it can neutralize the effects of its own poison and control the victim\'s movement and actions as if using <i>dominate monster</i> on the victim. The hellwasps quickly consume a living victim, dealing 2d4 points of Constitution damage per hour they inhabit a body. A body reduced to Constitution 0 is dead.</p><p>A hellwasp-inhabited creature is relatively easy to spot, since its skin crawls with the forms of insects inside. The swarm is intelligent enough to attempt to hide beneath loose clothing or a large cloak to keep its presence from being detected. The swarm can attempt a Disguise check to conceal its inhabitation of a host, with a -4 penalty if currently inhabiting a Small host.</p><p>A <i>remove disease</i> or <i>heal</i> spell cast on an inhabited victim forces the hellwasp swarm to abandon its host.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 18, initial and secondary damage 1d6 Dex. The save DC is Constitution-based.</p>\n</div><div topic=\"Hive Mind\" level=\"8\"><p><b>Hive Mind (Ex):</b> Any hellwasp swarm with at least 1 hit point per Hit Die (or 12 hit points, for a standard hellwasp swarm) forms a hive mind, giving it an Intelligence of 6. When a hellwasp swarm is reduced below this hit point threshold, it becomes mindless.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (577,'Swarm','Locust Swarm',NULL,'Diminutive','Vermin','Swarm','6d8-6 (21 hp)','+4','10 ft. (2 squares), fly 30 ft. (poor)','18 (+4 size, +4 Dex), touch 18, flat-footed 14','+4','-','Swarm (2d6)','Swarm (2d6)','10 ft.','0 ft.','Distraction','Darkvision 60 ft., immune to weapon damage, swarm traits, vermin traits','Fort +4, Ref +6, Will +2','Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2','Listen +4, Spot +4',NULL,'-',NULL,'Temperate plains','Solitary, cloud (2-7 swarms), or plague (11-20 swarms)','3','None','Always neutral','None','-','Distraction (Ex)','Locust swarm; CR 3; Diminutive vermin (swarm); HD 6d8-6; hp 21; Init +4; Spd 10 ft. (2 squares), fly 30 ft. (poor); AC 18 (+4 size, +4 dex), touch 18, flat-footed 14; Base Atk +4; Grp -; Atk Swarm (2d6); Full Atk Swarm (2d6); Space/Reach 10 ft./0 ft.; SA Distraction; SQ Darkvision 60 ft., immune to weapon damage, swarm traits, vermin traits; AL N; SV Fort +4, Ref +6, Will +2; Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2\n\nSkills and Feats: Listen +4, Spot +4; -','\n      <div topic=\"Locust Swarm\" level=\"3\"><p><h3>Locust Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Locust Swarm</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Vermin (Swarm)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8-6 (21 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), fly 30 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+4 size, +4 Dex), touch 18, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Swarm (2d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Swarm (2d6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Distraction<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immune to weapon damage, swarm traits, vermin traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +6, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 19, Con 8, Int -, Wis 10, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +4, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, cloud (2-7 swarms), or plague (11-20 swarms)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A locust swarm is a cloud of thousands of winged vermin that devours any organic material in its path.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A locust swarm surrounds and attacks any living prey it encounters. A swarm deals 2d6 points of damage to any creature whose space it occupies at the end of its move.</p><div topic=\"Distraction\" level=\"8\"><p><b>Distraction (Ex):</b> Any living creature that begins its turn with a locust swarm in its space must succeed on a DC 12 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A locust swarm has a +4 racial bonus on Listen and Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (578,'Swarm','Rat Swarm',NULL,'Tiny','Animal','Swarm','4d8 (13 hp)','+2','15 ft. (3 squares), climb 15 ft.','14 (+2 size, +2 Dex), touch 14, flat-footed 12','+3','-','Swarm (1d6 plus disease)','Swarm (1d6 plus disease)','10 ft.','0 ft.','Disease, distraction','Half damage from slashing and piercing, low-light vision, scent, swarm traits','Fort +4, Ref +6, Will +2','Str 2, Dex 15, Con 10, Int 2, Wis 12, Cha 2','Balance +10, Climb +10, Hide +14, Listen +6, Spot +7, Swim +10',NULL,'Alertness, Weapon Finesse',NULL,'Any','Solitary, pack (2-4 swarms), or infestation (7-12 swarms)','2','None','Always neutral','None','-','Disease (Ex), Distraction (Ex)','Rat swarm; CR 2; Tiny animal (swarm); HD 4d8; hp 13; Init +2; Spd 15 ft. (3 squares), climb 15 ft.; AC 14 (+2 size, +2 dex), touch 14, flat-footed 12; Base Atk +3; Grp -; Atk Swarm (1d6 plus disease); Full Atk Swarm (1d6 plus disease); Space/Reach 10 ft./0 ft.; SA Disease, distraction; SQ Half damage from slashing and piercing, low-light vision, scent, swarm traits; AL N; SV Fort +4, Ref +6, Will +2; Str 2, Dex 15, Con 10, Int 2, Wis 12, Cha 2\n\nSkills and Feats: Balance +10, Climb +10, Hide +14, Listen +6, Spot +7, Swim +10; Alertness, Weapon Finesse','\n      <div topic=\"Rat Swarm\" level=\"3\"><p><h3>Rat Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Rat Swarm</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Tiny Animal (Swarm)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d8 (13 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>